//! Level data (format version 3). World units are pixels, **y up**,
//! angles in radians. Everything is plain serde data so levels can be saved,
//! shared, edited, and generated by the builder.

use glam::Vec2;
use serde::{Deserialize, Serialize};

pub const FORMAT_VERSION: u32 = 3;

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum Shape {
    Poly { points: Vec<Vec2> },
    Rect { center: Vec2, size: Vec2, #[serde(default)] angle: f32 },
    Circle { center: Vec2, radius: f32 },
}

impl Shape {
    pub fn rect(min: Vec2, max: Vec2) -> Shape {
        Shape::Rect { center: (min + max) * 0.5, size: max - min, angle: 0.0 }
    }

    pub fn rect_at(center: Vec2, size: Vec2, angle: f32) -> Shape {
        Shape::Rect { center, size, angle }
    }

    /// Counter-clockwise outline. Circles are 24-gons (or `segments`).
    pub fn outline(&self) -> Vec<Vec2> {
        self.outline_n(24)
    }

    pub fn outline_n(&self, segments: usize) -> Vec<Vec2> {
        match self {
            Shape::Poly { points } => points.clone(),
            Shape::Rect { center, size, angle } => {
                let h = *size * 0.5;
                let rot = Vec2::from_angle(*angle);
                [Vec2::new(-h.x, -h.y), Vec2::new(h.x, -h.y), Vec2::new(h.x, h.y), Vec2::new(-h.x, h.y)]
                    .into_iter()
                    .map(|p| *center + rot.rotate(p))
                    .collect()
            }
            Shape::Circle { center, radius } => (0..segments)
                .map(|i| {
                    let a = i as f32 / segments as f32 * std::f32::consts::TAU;
                    *center + Vec2::new(a.cos(), a.sin()) * *radius
                })
                .collect(),
        }
    }

    pub fn center(&self) -> Vec2 {
        match self {
            Shape::Poly { points } => points.iter().copied().sum::<Vec2>() / points.len().max(1) as f32,
            Shape::Rect { center, .. } | Shape::Circle { center, .. } => *center,
        }
    }

    pub fn translated(&self, d: Vec2) -> Shape {
        match self {
            Shape::Poly { points } => Shape::Poly { points: points.iter().map(|p| *p + d).collect() },
            Shape::Rect { center, size, angle } => Shape::Rect { center: *center + d, size: *size, angle: *angle },
            Shape::Circle { center, radius } => Shape::Circle { center: *center + d, radius: *radius },
        }
    }

    pub fn bounds(&self) -> (Vec2, Vec2) {
        let o = self.outline();
        let mut min = Vec2::splat(f32::MAX);
        let mut max = Vec2::splat(f32::MIN);
        for p in o {
            min = min.min(p);
            max = max.max(p);
        }
        (min, max)
    }
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Material {
    #[default]
    Ground,
    Ice,
    Sticky,
    Bouncy,
    Stone,
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Theme {
    #[default]
    Hollow,
    Drip,
    Fungus,
    Vines,
    Stoneworks,
    Lake,
    Chimney,
    Toys,
    CaveIn,
    Well,
    Playroom,
    Kids,
    Party,
}

#[derive(Copy, Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Mode {
    Story,
    /// 2.x race maps (kept so imported maps load; party plays them as KOTH).
    Race,
    Koth,
    Kids,
    Sandbox,
}

/// Solid level geometry (rendered as candy-coated rock; never moves).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Terrain {
    pub shape: Shape,
    #[serde(default)]
    pub material: Material,
    /// Jump up through it, land on top.
    #[serde(default)]
    pub one_way: bool,
}

/// Soft ground: a mesh tethered to its rest pose. Dents when you land,
/// jiggles when things hit it, stays where it was put.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Jelly {
    pub shape: Shape,
    #[serde(default)]
    pub material: Material,
    /// 0 = firm, 1 = very wobbly.
    #[serde(default = "half")]
    pub wobble: f32,
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum Pins {
    /// Left and right edges pinned (a bridge).
    #[default]
    Ends,
    Left,
    Right,
    Corners,
    /// Top edge pinned (hanging curtain).
    Top,
    /// Every particle softly tethered home (a floating jelly slab).
    Home,
    /// Not pinned at all.
    None,
}

/// A soft rectangular sheet: bridges, floating slabs, membranes.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SoftPlatform {
    #[serde(default)]
    pub id: String,
    pub center: Vec2,
    pub size: Vec2,
    #[serde(default)]
    pub angle: f32,
    #[serde(default)]
    pub pins: Pins,
    /// 0 = floppy, 1 = firm.
    #[serde(default = "half")]
    pub stiffness: f32,
    #[serde(default)]
    pub material: Material,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum PropKind {
    Block,
    Ball,
    Star,
    /// A toy with a custom outline.
    Custom { outline: Vec<Vec2> },
}

/// A free dynamic softbody: blocks, balls, toys.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Prop {
    #[serde(default)]
    pub id: String,
    pub kind: PropKind,
    pub center: Vec2,
    /// Width/height for blocks and stars; diameter in x for balls.
    pub size: Vec2,
    #[serde(default)]
    pub angle: f32,
    #[serde(default = "one")]
    pub mass: f32,
    #[serde(default)]
    pub material: Material,
    /// Hex color, e.g. "#ff8fb1". Empty = theme default.
    #[serde(default)]
    pub color: String,
    /// Can players pick it up / is it heavy furniture?
    #[serde(default)]
    pub pinned: bool,
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum MoverMotion {
    /// Follow the path and loop back to the start.
    #[default]
    Loop,
    /// Back and forth along the path.
    PingPong,
    /// Wait, slam to the end of the path quickly, wait, rise slowly.
    Crusher { slam: f32, hold: f32, rise: f32, wait: f32 },
    /// Spin around the shape's centre at `speed` rad/s.
    Spin { speed: f32 },
    /// Back and forth along the path, pausing `hold` seconds at each end
    /// (easy-to-board elevators). `period` is the travel time one way.
    Lift { hold: f32 },
}

/// Kinematic (script-moved) geometry: elevators, pistons, crushers, fans.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Mover {
    #[serde(default)]
    pub id: String,
    pub shape: Shape,
    /// Waypoints as offsets from the shape's authored position; the first
    /// is usually (0,0).
    #[serde(default)]
    pub path: Vec<Vec2>,
    #[serde(default)]
    pub motion: MoverMotion,
    /// Seconds per full cycle (Loop / PingPong).
    #[serde(default = "two")]
    pub period: f32,
    /// 0..1 phase offset.
    #[serde(default)]
    pub phase: f32,
    #[serde(default)]
    pub material: Material,
    /// If set, only moves while the named trigger is active.
    #[serde(default)]
    pub trigger: String,
    /// Touching it pops a blob (spinning blades, spiky drips).
    #[serde(default)]
    pub lethal: bool,
    /// Spikes on its underside (falling rocks, spiked crushers): touching
    /// the bottom face pops you.
    #[serde(default, skip_serializing_if = "is_false")]
    pub spiked: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum RopeEnd {
    /// Tied to a fixed point in the world.
    World { at: Vec2 },
    /// Tied to the centre of a prop / platform by id.
    Body { id: String },
    /// Dangling free end (vines). Starts at `at`.
    Free { at: Vec2 },
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RopeStyle {
    #[default]
    Vine,
    Rope,
    Chain,
    Slinky,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct RopeDef {
    #[serde(default)]
    pub id: String,
    pub from: RopeEnd,
    pub to: RopeEnd,
    /// Rope length; 0 = distance between the ends.
    #[serde(default)]
    pub length: f32,
    #[serde(default = "yes")]
    pub grabbable: bool,
    #[serde(default)]
    pub style: RopeStyle,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq)]
#[serde(tag = "type", rename_all = "snake_case")]
pub enum ZoneKind {
    /// Constant acceleration on bodies inside (updrafts, gusts).
    Wind { accel: Vec2 },
    /// Buoyancy (upward accel when submerged) + drag + current.
    Water { buoyancy: f32, drag: f32, current: Vec2 },
    /// Instant pop.
    Kill,
    /// Surface conveyor: pushes contacting bodies sideways.
    Conveyor { speed: f32 },
    /// Override gravity inside.
    Gravity { gravity: Vec2 },
    /// Heavy drag (goo).
    Goo { drag: f32 },
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Zone {
    #[serde(default)]
    pub id: String,
    pub shape: Shape,
    pub kind: ZoneKind,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct SpringPad {
    pub pos: Vec2,
    /// Launch direction (radians, 0 = right, π/2 = up).
    #[serde(default = "up")]
    pub angle: f32,
    #[serde(default = "pad_width")]
    pub width: f32,
    /// Launch speed in px/s.
    #[serde(default = "pad_power")]
    pub power: f32,
}

/// Shape of a [`BouncyMushroom`] cap.
#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MushroomShape {
    /// A flat springy pad: launches along its `angle`, like a spring.
    #[default]
    Flat,
    /// A rounded dome: launches along the dome's normal where you hit it.
    Dome,
    /// A ball on a stalk: launches straight away from its centre (any side).
    Ball,
}

impl MushroomShape {
    /// Height of the cap above the stalk top for a cap `size` wide.
    pub fn cap_height(self, size: f32) -> f32 {
        match self {
            MushroomShape::Flat => (size * 0.2).max(18.0),
            MushroomShape::Dome => size * 0.4,
            MushroomShape::Ball => size,
        }
    }
}

/// A bouncy mushroom: a soft, physical cap on a rock stalk that launches
/// whatever lands on it. Swelling (holding the button) as you hit it launches
/// you much higher. The stalk is plain terrain (the builder adds it).
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct BouncyMushroom {
    /// Top of the stalk (the cap sits on it).
    pub pos: Vec2,
    #[serde(default)]
    pub shape: MushroomShape,
    /// Cap width (ball: diameter).
    #[serde(default = "cap_size")]
    pub size: f32,
    /// Launch speed in px/s.
    #[serde(default = "pad_power")]
    pub power: f32,
    /// Flat caps: launch direction (radians, π/2 = up).
    #[serde(default = "up")]
    pub angle: f32,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Spikes {
    /// Base line of the spike strip; teeth point to the left of a→b
    /// (so a→b left-to-right points them up).
    pub a: Vec2,
    pub b: Vec2,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Checkpoint {
    pub pos: Vec2,
}

#[derive(Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum NpcRole {
    /// A Huddle blob that idles and wobbles.
    #[default]
    Huddle,
    /// Trapped Huddle blob: free it (touch it) and it follows you.
    Trapped,
    /// Follows the nearest player.
    Follower,
    /// Wanders around (kids mode friends).
    Wanderer,
    Glimmer,
    Granny,
    Reg,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Npc {
    #[serde(default)]
    pub id: String,
    pub pos: Vec2,
    #[serde(default)]
    pub role: NpcRole,
    #[serde(default)]
    pub color: String,
    /// Radius in px (blob size).
    #[serde(default = "npc_radius")]
    pub radius: f32,
}

/// Fires a story script (speech bubble, mini-cutscene) when a player enters.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct StoryTrigger {
    pub shape: Shape,
    pub script: String,
    #[serde(default = "yes")]
    pub once: bool,
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Decor {
    /// Decor sprite / procedural kind, e.g. "mushroom", "crystal", "drip",
    /// "glowworm", "sock", "crayon", "lantern".
    pub kind: String,
    pub pos: Vec2,
    #[serde(default = "one")]
    pub scale: f32,
    #[serde(default)]
    pub angle: f32,
    /// Negative = behind gameplay, positive = in front.
    #[serde(default = "neg_one")]
    pub depth: f32,
}

#[derive(Copy, Clone, Debug, Default, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MouthKind {
    /// Sealed tunnel back to the previous chapter (scenery: can't be entered).
    Entry,
    /// The tunnel you walk into to finish the level (the goal sits inside).
    #[default]
    Exit,
}

/// A cave mouth: a tunnel opening in the rock at the start or end of a
/// level, glowing with the colour of the chapter it leads to.
#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct CaveMouth {
    /// Floor point at the opening, on the wall face.
    pub pos: Vec2,
    /// Which way the tunnel runs into the rock: +1 = towards +x, -1 = -x.
    pub facing: f32,
    #[serde(default)]
    pub kind: MouthKind,
    /// Theme whose light fills the tunnel (the neighbouring chapter's).
    #[serde(default)]
    pub theme: Theme,
    /// Opening height (y) and tunnel depth (x).
    #[serde(default = "mouth_size")]
    pub size: Vec2,
    /// Daylight beyond (the finale): warm sunlight instead of cave glow.
    #[serde(default, skip_serializing_if = "is_false")]
    pub daylight: bool,
}

impl CaveMouth {
    /// The tunnel interior: (min, max) corners.
    pub fn interior(&self) -> (Vec2, Vec2) {
        let a = self.pos;
        let b = self.pos + Vec2::new(self.facing.signum() * self.size.x, self.size.y);
        (a.min(b), a.max(b))
    }
}

#[derive(Clone, Debug, Serialize, Deserialize)]
pub struct Level {
    #[serde(default = "format_version")]
    pub version: u32,
    pub id: String,
    pub name: String,
    #[serde(default)]
    pub theme: Theme,
    #[serde(default)]
    pub modes: Vec<Mode>,
    pub spawn: Vec2,
    /// Anything that falls below this pops.
    pub kill_y: f32,
    #[serde(default)]
    pub gravity: Option<Vec2>,
    #[serde(default)]
    pub terrain: Vec<Terrain>,
    #[serde(default)]
    pub jelly: Vec<Jelly>,
    #[serde(default)]
    pub platforms: Vec<SoftPlatform>,
    #[serde(default)]
    pub props: Vec<Prop>,
    #[serde(default)]
    pub movers: Vec<Mover>,
    #[serde(default)]
    pub ropes: Vec<RopeDef>,
    #[serde(default)]
    pub zones: Vec<Zone>,
    #[serde(default)]
    pub springs: Vec<SpringPad>,
    #[serde(default)]
    pub spikes: Vec<Spikes>,
    /// Bouncy mushrooms (soft launch caps).
    #[serde(default)]
    pub mushrooms: Vec<BouncyMushroom>,
    #[serde(default)]
    pub checkpoints: Vec<Checkpoint>,
    /// Glow drops to collect.
    #[serde(default)]
    pub pickups: Vec<Vec2>,
    #[serde(default)]
    pub npcs: Vec<Npc>,
    #[serde(default)]
    pub goal: Option<Shape>,
    #[serde(default)]
    pub hills: Vec<Shape>,
    #[serde(default)]
    pub story: Vec<StoryTrigger>,
    #[serde(default)]
    pub decor: Vec<Decor>,
    /// Entry / exit cave mouths (story chapters).
    #[serde(default, skip_serializing_if = "Vec::is_empty")]
    pub mouths: Vec<CaveMouth>,
    /// Cutscene played before the level starts (story mode).
    #[serde(default)]
    pub intro: String,
    /// Cutscene played after the goal is reached (story mode).
    #[serde(default)]
    pub outro: String,
}

impl Level {
    pub fn new(id: &str, name: &str) -> Level {
        Level {
            version: FORMAT_VERSION,
            id: id.into(),
            name: name.into(),
            theme: Theme::Hollow,
            modes: vec![Mode::Story],
            spawn: Vec2::ZERO,
            kill_y: -2000.0,
            gravity: None,
            terrain: Vec::new(),
            jelly: Vec::new(),
            platforms: Vec::new(),
            props: Vec::new(),
            movers: Vec::new(),
            ropes: Vec::new(),
            zones: Vec::new(),
            springs: Vec::new(),
            spikes: Vec::new(),
            mushrooms: Vec::new(),
            checkpoints: Vec::new(),
            pickups: Vec::new(),
            npcs: Vec::new(),
            goal: None,
            hills: Vec::new(),
            story: Vec::new(),
            decor: Vec::new(),
            mouths: Vec::new(),
            intro: String::new(),
            outro: String::new(),
        }
    }

    pub fn to_json(&self) -> String {
        serde_json::to_string_pretty(self).expect("level serialises")
    }

    pub fn from_json(s: &str) -> Result<Level, serde_json::Error> {
        serde_json::from_str(s)
    }

    /// Bounding box of all solid geometry.
    pub fn bounds(&self) -> (Vec2, Vec2) {
        let mut min = Vec2::splat(f32::MAX);
        let mut max = Vec2::splat(f32::MIN);
        let shapes = self
            .terrain
            .iter()
            .map(|t| &t.shape)
            .chain(self.jelly.iter().map(|j| &j.shape))
            .chain(self.movers.iter().map(|m| &m.shape));
        for s in shapes {
            let (a, b) = s.bounds();
            min = min.min(a);
            max = max.max(b);
        }
        for p in self.platforms.iter().map(|p| p.center) {
            min = min.min(p);
            max = max.max(p);
        }
        if min.x > max.x {
            return (self.spawn - Vec2::splat(500.0), self.spawn + Vec2::splat(500.0));
        }
        (min, max)
    }

    /// All respawn points in order: the level spawn, then each checkpoint.
    pub fn respawn_points(&self) -> Vec<Vec2> {
        std::iter::once(self.spawn).chain(self.checkpoints.iter().map(|c| c.pos)).collect()
    }
}

fn half() -> f32 {
    0.5
}
fn one() -> f32 {
    1.0
}
fn two() -> f32 {
    2.0
}
fn neg_one() -> f32 {
    -1.0
}
fn yes() -> bool {
    true
}
fn up() -> f32 {
    std::f32::consts::FRAC_PI_2
}
fn cap_size() -> f32 {
    160.0
}
fn pad_width() -> f32 {
    90.0
}
fn pad_power() -> f32 {
    1400.0
}
fn npc_radius() -> f32 {
    30.0
}
fn is_false(b: &bool) -> bool {
    !*b
}
fn mouth_size() -> Vec2 {
    Vec2::new(560.0, 300.0)
}
fn format_version() -> u32 {
    FORMAT_VERSION
}
